<template><section class="kfe-admin-section"><label class="kfe-form-label" for="admin-month">Month View</label><input id="admin-month" v-model="monthModel" type="month" @change="$emit('change')"></section><section class="kfe-admin-section"><h2>{{month}} · PERIOD OVERVIEW</h2><div class="kfe-admin-grid"><article><span>Revenue</span><strong>{{money(period?.revenuePaise)}}</strong></article><article><span>Business Cost</span><strong>{{money(period?.costsPaise)}}</strong></article><article><span>Profit</span><strong>{{money(period?.profitPaise)}}</strong></article><article><span>Business KM</span><strong>{{period?.businessKm==null?'Unavailable':`${period.businessKm} km`}}</strong></article></div></section><section class="kfe-admin-section"><h2>EXPENSE BREAKDOWN</h2><div class="kfe-admin-grid"><article><span>Fuel</span><strong>{{money(expenseBreakdown.fuelPaise)}}</strong></article><article><span>Maintenance</span><strong>{{money(expenseBreakdown.maintenancePaise)}}</strong></article><article><span>Business Expenses</span><strong>{{money(expenseBreakdown.businessExpensePaise??expenseBreakdown.expensesPaise)}}</strong></article></div></section><section class="kfe-admin-section"><h2>LOAN STATUS</h2><p class="kfe-boundary-note">{{loanCount?`${loanCount} authoritative loan record(s) available.`:'No authoritative loan status is currently available.'}}</p></section><section class="kfe-admin-section"><h2>WEEKLY</h2><div class="kfe-admin-list"><button v-for="item in weekly" :key="item.week" type="button" @click="$emit('week',item.week)"><span>Week {{item.week}}</span><span>View Week ›</span></button></div></section></template>
<script setup>import {computed} from 'vue';const props=defineProps({month:{type:String,required:true},period:{type:Object,default:()=>({})},expenseBreakdown:{type:Object,default:()=>({})},weekly:{type:Array,default:()=>[]},loanCount:{type:Number,default:0},money:{type:Function,required:true}});const emit=defineEmits(['change','week']);const monthModel=computed({get:()=>props.month,set:v=>emit('update:month',v)})</script>
